number of falls:


::: {.cell}

```{.r .cell-code}
res_falls_home <- upswr_est(ti, Mi, xbar_pop = Mbar_U, tx_pop = M0, method = "mean", show.details = FALSE)
res_falls_home$estimate |> format_est_gt("hh_ybar")
